package org.sigf.services;
import java.sql.*;import java.math.*;import java.util.*;import org.mindrot.jbcrypt.BCrypt;import org.sigf.config.Database;import org.sigf.security.Security;import org.sigf.repositories.*;
public final class AdministrationService {
 private final Database db;public AdministrationService(Database db){this.db=db;}
 private static void required(String s){if(s==null||s.isBlank())throw new IllegalArgumentException("Complete los campos obligatorios");}
 public void internalSeries(Security.User u,String code,long next)throws SQLException{u.admin();if(code==null||!code.matches("[A-Za-z0-9_-]{1,20}")||next<1)throw new IllegalArgumentException("Serie o número inválido");try(Connection c=db.connection()){c.setAutoCommit(false);try{Security.verify(c,u,true);try(Statement lock=c.createStatement()){lock.execute("select id from internal_series where id=1 for update");}try(PreparedStatement q=c.prepareStatement("select coalesce(max(number),0) from internal_document where series=?")){q.setString(1,code);try(ResultSet r=q.executeQuery()){r.next();if(next<=r.getLong(1))throw new IllegalArgumentException("El próximo número debe ser mayor que los ya utilizados en esa serie");}}try(PreparedStatement q=c.prepareStatement("update internal_series set code=?,next_number=? where id=1")){q.setString(1,code);q.setLong(2,next);if(q.executeUpdate()!=1)throw new IllegalStateException("No existe la serie interna");}AuditRepository.write(c,u,"INTERNAL_SERIES_CHANGE",code+" / "+next);c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public void user(Security.User actor,Long id,String username,String password,String role,boolean active)throws SQLException{actor.admin();required(username);if(!Set.of("ADMIN","CASHIER").contains(role))throw new IllegalArgumentException("Rol inválido");if((id==null||!password.isEmpty())&&password.length()<12)throw new IllegalArgumentException("La contraseña debe tener al menos 12 caracteres");if(id!=null&&id==actor.id()&&(!active||!role.equals("ADMIN")))throw new IllegalArgumentException("No puede desactivar o degradar su propia cuenta");String hash=password.isEmpty()?null:BCrypt.hashpw(password,BCrypt.gensalt(12));try(Connection c=db.connection()){c.setAutoCommit(false);try{Security.verify(c,actor,true);String sql=id==null?"insert into app_user(username,role,active,password_hash) values(?,?,?,?)":"update app_user set username=?,role=?,active=?,password_hash=coalesce(?,password_hash),session_version=gen_random_uuid() where id=?";try(PreparedStatement s=c.prepareStatement(sql)){s.setString(1,username.trim());s.setString(2,role);s.setBoolean(3,active);s.setString(4,hash);if(id!=null)s.setLong(5,id);if(s.executeUpdate()!=1)throw new IllegalArgumentException("Usuario inexistente");}AuditRepository.write(c,actor,"USER_CHANGE",username);c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public void setting(Security.User u,String key,String value)throws SQLException{u.admin();required(value);if(key.equals("currency")&&!value.equals("NIO"))throw new IllegalArgumentException("Esta instalación opera únicamente en córdobas (NIO)");if(!Set.of("pharmacy_name","currency","business_details","expiry_days").contains(key))throw new IllegalArgumentException("Parámetro desconocido");if(key.equals("tax_rate")){BigDecimal n=new BigDecimal(value);if(n.signum()<0||n.compareTo(BigDecimal.ONE)>0)throw new IllegalArgumentException("Impuesto debe estar entre 0 y 1");}if(key.equals("expiry_days")&&Integer.parseInt(value)<0)throw new IllegalArgumentException("Días inválidos");try(Connection c=db.connection()){c.setAutoCommit(false);try(PreparedStatement s=c.prepareStatement("insert into setting(key,value) values(?,?) on conflict(key) do update set value=excluded.value")){Security.verify(c,u,true);s.setString(1,key);s.setString(2,value);s.executeUpdate();AuditRepository.write(c,u,"SETTING_CHANGE",key);c.commit();}catch(Exception e){c.rollback();throw e;}}}
}
